// zonedOrg is an organization in tz with an invoice to take payments on, and a function that records a payment.
func zonedOrg(t *testing.T, tz string) (*store.Store, string, func(int64, money.Currency, store.PaymentStatus, time.Time)) {
	t.Helper()
	st := store.New()
	at := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	o, err := st.CreateOrg("Z", store.OrgTeam, tz, 0, at)
	if err != nil {
		t.Fatal(err)
	}
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", at)
	inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, at)
	pay := func(amount int64, cur money.Currency, status store.PaymentStatus, when time.Time) {
		if _, err := st.CreatePayment(store.Payment{OrgID: o.ID, InvoiceID: inv.ID, Amount: amount, Currency: cur, Status: status}, when); err != nil {
			t.Fatal(err)
		}
	}
	return st, o.ID, pay
}

func TestRevenueUsesOrgTimeZone(t *testing.T) {
	ny, err := time.LoadLocation("America/New_York")
	if err != nil {
		t.Fatal(err)
	}
	st, orgID, pay := zonedOrg(t, "America/New_York")
	// 23:30 on 2 March in New York is 04:30 UTC on 3 March.
	pay(1000, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 2, 23, 30, 0, 0, ny))
	got, err := Revenue(st, orgID, "2026-03-02", "2026-03-02")
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0] != (DayRevenue{Date: "2026-03-02", Currency: money.USD, Amount: 1000, Payments: 1}) {
		t.Fatalf("Revenue = %+v", got)
	}
}

func TestRevenueReportDaylightSaving(t *testing.T) {
	ny, _ := time.LoadLocation("America/New_York")
	// Clocks go forward on 8 March 2026 in New York, so that day is 23 hours long.
	st, orgID, pay := zonedOrg(t, "America/New_York")
	pay(100, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 7, 12, 0, 0, 0, ny))
	pay(200, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 8, 0, 30, 0, 0, ny))
	pay(300, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 8, 23, 30, 0, 0, ny))
	pay(400, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 9, 0, 30, 0, 0, ny))
	r, err := RevenueReport(st, orgID, "2026-03-07", "2026-03-09", ByDay)
	if err != nil {
		t.Fatal(err)
	}
	want := []Bucket{
		{Start: "2026-03-07", Amounts: map[money.Currency]int64{money.USD: 100}, Payments: 1},
		{Start: "2026-03-08", Amounts: map[money.Currency]int64{money.USD: 500}, Payments: 2},
		{Start: "2026-03-09", Amounts: map[money.Currency]int64{money.USD: 400}, Payments: 1},
	}
	if r.TimeZone != "America/New_York" || r.Group != ByDay || len(r.Buckets) != len(want) {
		t.Fatalf("report = %+v", r)
	}
	for i := range want {
		if !reflect.DeepEqual(r.Buckets[i], want[i]) {
			t.Fatalf("bucket %d = %+v, want %+v", i, r.Buckets[i], want[i])
		}
	}
}

func TestRevenueReportGroups(t *testing.T) {
	ny, _ := time.LoadLocation("America/New_York")
	st, orgID, pay := zonedOrg(t, "America/New_York")
	pay(100, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 7, 12, 0, 0, 0, ny))  // Saturday, week of 2 March
	pay(200, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 8, 23, 30, 0, 0, ny)) // Sunday, week of 2 March
	pay(50, money.EUR, store.PaymentSucceeded, time.Date(2026, 3, 9, 0, 30, 0, 0, ny))   // Monday, week of 9 March
	pay(999, money.USD, store.PaymentFailed, time.Date(2026, 3, 9, 1, 0, 0, 0, ny))
	pay(1000, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 14, 10, 0, 0, 0, ny))
	pay(5, money.USD, store.PaymentSucceeded, time.Date(2026, 2, 28, 10, 0, 0, 0, ny)) // before the range

	t.Run("week", func(t *testing.T) {
		r, err := RevenueReport(st, orgID, "2026-03-04", "2026-03-15", ByWeek)
		if err != nil {
			t.Fatal(err)
		}
		want := []Bucket{
			{Start: "2026-03-02", Amounts: map[money.Currency]int64{money.USD: 300}, Payments: 2},
			{Start: "2026-03-09", Amounts: map[money.Currency]int64{money.USD: 1000, money.EUR: 50}, Payments: 2},
		}
		if !reflect.DeepEqual(r.Buckets, want) {
			t.Fatalf("weeks = %+v", r.Buckets)
		}
	})
	t.Run("month", func(t *testing.T) {
		r, err := RevenueReport(st, orgID, "2026-02-20", "2026-04-02", ByMonth)
		if err != nil {
			t.Fatal(err)
		}
		want := []Bucket{
			{Start: "2026-02-01", Amounts: map[money.Currency]int64{}, Payments: 0},
			{Start: "2026-03-01", Amounts: map[money.Currency]int64{money.USD: 1300, money.EUR: 50}, Payments: 4},
			{Start: "2026-04-01", Amounts: map[money.Currency]int64{}, Payments: 0},
		}
		if !reflect.DeepEqual(r.Buckets, want) {
			t.Fatalf("months = %+v", r.Buckets)
		}
	})
	t.Run("empty days are kept", func(t *testing.T) {
		r, err := RevenueReport(st, orgID, "2026-03-10", "2026-03-12", "")
		if err != nil {
			t.Fatal(err)
		}
		if r.Group != ByDay || len(r.Buckets) != 3 {
			t.Fatalf("report = %+v", r)
		}
		for _, b := range r.Buckets {
			if b.Amounts == nil || len(b.Amounts) != 0 || b.Payments != 0 {
				t.Fatalf("bucket = %+v", b)
			}
		}
	})
	t.Run("bad group", func(t *testing.T) {
		if _, err := RevenueReport(st, orgID, "2026-03-01", "2026-03-05", "quarter"); !errors.Is(err, ErrInvalidGroup) {
			t.Fatalf("err = %v", err)
		}
	})
}

func TestRevenueReportRange(t *testing.T) {
	st, orgID, _ := zonedOrg(t, "Europe/Berlin")
	for _, c := range []struct {
		from, to string
		want     error
	}{
		{"2026-03-01", "", ErrInvalidDate},
		{"2026-03-05", "2026-03-01", ErrInvalidRange},
		{"2026-01-01", "2027-01-02", ErrInvalidRange},
	} {
		if _, err := RevenueReport(st, orgID, c.from, c.to, ByDay); !errors.Is(err, c.want) {
			t.Errorf("RevenueReport(%s, %s) = %v, want %v", c.from, c.to, err, c.want)
		}
	}
	r, err := RevenueReport(st, orgID, "2026-01-01", "2026-12-31", ByMonth)
	if err != nil || len(r.Buckets) != 12 || r.TimeZone != "Europe/Berlin" {
		t.Fatalf("a full year: %+v, %v", r, err)
	}
}
