		}
	})
	t.Run("bad group", func(t *testing.T) {
		if _, err := RevenueReport(st, orgID, "2026-03-01", "2026-03-05", "quarter"); !errors.Is(err, ErrInvalidGroup) {
			t.Fatalf("err = %v", err)
		}
	})
}

func TestRevenueReportRange(t *testing.T) {
	st, orgID, _ := zonedOrg(t, "Europe/Berlin")
	for _, c := range []struct {
		from, to string
		want     error
	}{
		{"2026-03-01", "", ErrInvalidDate},
		{"2026-03-05", "2026-03-01", ErrInvalidRange},
		{"2026-01-01", "2027-01-02", ErrInvalidRange},
	} {
		if _, err := RevenueReport(st, orgID, c.from, c.to, ByDay); !errors.Is(err, c.want) {
			t.Errorf("RevenueReport(%s, %s) = %v, want %v", c.from, c.to, err, c.want)
		}
	}
	r, err := RevenueReport(st, orgID, "2026-01-01", "2026-12-31", ByMonth)
	if err != nil || len(r.Buckets) != 12 || r.TimeZone != "Europe/Berlin" {
		t.Fatalf("a full year: %+v, %v", r, err)
	}
}
